function downloadAccessDialog(title,message,action='OK',cancel=false){return new Promise(resolve=>{const d=document.createElement('dialog');d.style.cssText='width:min(440px,calc(100% - 32px));padding:24px;border:1px solid #ded3c4;border-radius:14px;background:#fcfaf6;color:#102438;box-shadow:0 20px 70px #10243844';d.innerHTML='<style>dialog::backdrop{background:#10243866}</style><div style="color:#a47b36;font-size:12px;letter-spacing:1px">PREVAIL FAMILY LAW</div><h2 style="font:600 23px Georgia;margin:12px 0"></h2><p style="font-size:14px;line-height:1.6;overflow-wrap:anywhere"></p><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:22px"></div>';d.querySelector('h2').textContent=title;d.querySelector('p').textContent=message;const footer=d.lastElementChild;const add=(label,value)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.style.cssText='padding:10px 15px;border-radius:7px;border:1px solid #a47b36;background:'+(value?'#102438':'#fcfaf6')+';color:'+(value?'white':'#102438')+';cursor:pointer';b.onclick=()=>d.close(value?'yes':'no');footer.append(b);};if(cancel)add('Cancel',false);add(action,true);d.addEventListener('close',()=>{resolve(d.returnValue==='yes');d.remove();},{once:true});document.body.append(d);d.showModal();});}
