  function collectInvoice(form,p){const rows=[...form.querySelectorAll('.pf-bill-line')].map(r=>({kind:r.dataset.kind,date:r.querySelector('[data-entry-date]').value,staff:r.querySelector('[data-staff]').value, included:r.querySelector('[data-include]').checked,billable:r.querySelector('[data-billable]').checked,description:r.querySelector('[data-desc]').value.trim(),quantity:Number(r.querySelector('[data-qty]').value),rate:Number(r.querySelector('[data-rate]').value),writeOff:r.querySelector('[data-wo]').checked}));if(!rows.length||rows.some(r=>!r.description||!Number.isFinite(r.quantity)||r.quantity<=0||!Number.isFinite(r.rate)||r.rate<0)){setStatus(form,'Add valid billing entries.',true);return false;}if(p.dueDate<p.issueDate){setStatus(form,'Due date must not precede issue date.',true);return false;}const round=n=>Math.round(n*100)/100;const sum=k=>round(rows.filter(r=>r.kind===k&&r.included&&r.billable&&!r.writeOff).reduce((n,r)=>n+round(r.quantity*r.rate),0));p.lineItems=rows;p.fees=sum('Fee');p.disbursements=sum('Disbursement');p.discount=round(p.fees*Number(p.discountPercent||0)/100);p.subtotal=round(p.fees+p.disbursements-p.discount+Number(p.surcharge||0));p.gst=round(p.subtotal*Number(p.gstRate||0)/100);p.total=round(p.subtotal+p.gst);return true;}
  function recordPayload(form) {
    const payload = {};
    let file = null;
    for (const [key, entry] of new FormData(form).entries()) {
      if (entry instanceof File) { if (entry.size) file = entry; continue; }
      const value = String(entry).trim();
      if (!value) continue;
      const control = form.elements.namedItem(key);
      payload[key] = control && control.type === 'number' ? Number(value) : value;
    }
    if (form.id === 'pm-receipt') payload.transactionType = 'Receipt';
    if (form.id === 'pm-withdraw') payload.transactionType = 'Withdrawal';
    if (form.id === 'pm-reconcile') payload.transactionType = 'Reconciliation';
    if (form.id === 'pm-expense' && payload.amount) payload.amount = Number(payload.amount);
    return {payload,file};
  }
